// Verify X-Signature = HMAC-SHA256(N8N_SHARED_SECRET, raw request body).
// Django sends compact JSON (separators ',' ':'), so prefer the RAW body.
const crypto = require('crypto');
const secret = $env.N8N_SHARED_SECRET;
if (!secret) { throw new Error('N8N_SHARED_SECRET is not set'); }

const item = $input.first();
const headers = item.json.headers || {};
const sig = headers['x-signature'] || headers['X-Signature'];

// Prefer the exact raw body bytes captured by the webhook (rawBody:true).
let rawBody = item.binary && item.binary.data
  ? Buffer.from(item.binary.data.data, 'base64').toString('utf8')
  : (typeof item.json.body === 'string' ? item.json.body : JSON.stringify(item.json.body));

const expected = crypto.createHmac('sha256', secret).update(rawBody, 'utf8').digest('hex');
if (!sig || expected !== sig) {
  throw new Error('invalid signature');
}

// Parse the verified payload for downstream nodes.
const payload = typeof item.json.body === 'string' ? JSON.parse(item.json.body) : item.json.body;
return [{ json: payload }];

// Build a multilingual HTML order-confirmation email.
const p = $input.first().json;
const lang = (p.language || 'en').toLowerCase();
const d = p.data || {};
const sym = { EUR: '€', USD: '$', GBP: '£' }[d.currency] || (d.currency ? d.currency + ' ' : '');
const money = (v) => sym + Number(v || 0).toFixed(2);

const t = {
  en: { subject: `Order ${d.order_number} confirmed`, hi: `Hi ${d.first_name || ''},`, intro: 'Thanks for your order! We have received your payment and are getting it ready.', items: 'Items', subtotal: 'Subtotal', shipping: 'Shipping', tax: 'Tax', total: 'Total', ship_to: 'Shipping to', eta: 'Estimated delivery', days: 'business days', thanks: 'Thank you for shopping with Glitchy.' },
  it: { subject: `Ordine ${d.order_number} confermato`, hi: `Ciao ${d.first_name || ''},`, intro: 'Grazie per il tuo ordine! Abbiamo ricevuto il pagamento e lo stiamo preparando.', items: 'Articoli', subtotal: 'Subtotale', shipping: 'Spedizione', tax: 'IVA', total: 'Totale', ship_to: 'Spedizione a', eta: 'Consegna stimata', days: 'giorni lavorativi', thanks: 'Grazie per aver acquistato da Glitchy.' },
  fr: { subject: `Commande ${d.order_number} confirmée`, hi: `Bonjour ${d.first_name || ''},`, intro: 'Merci pour votre commande ! Nous avons reçu votre paiement et la préparons.', items: 'Articles', subtotal: 'Sous-total', shipping: 'Livraison', tax: 'TVA', total: 'Total', ship_to: 'Livraison à', eta: 'Livraison estimée', days: 'jours ouvrés', thanks: 'Merci d’avoir choisi Glitchy.' }
}[lang] || null;
const L = t || ({
  subject: `Order ${d.order_number} confirmed`, hi: `Hi ${d.first_name || ''},`, intro: 'Thanks for your order!', items: 'Items', subtotal: 'Subtotal', shipping: 'Shipping', tax: 'Tax', total: 'Total', ship_to: 'Shipping to', eta: 'Estimated delivery', days: 'business days', thanks: 'Thank you for shopping with Glitchy.'
});

const rows = (d.items || []).map(it => `<tr><td style="padding:6px 8px;border-bottom:1px solid #eee">${it.name}${it.variant ? ' – ' + it.variant : ''}</td><td style="padding:6px 8px;border-bottom:1px solid #eee;text-align:center">${it.qty}</td><td style="padding:6px 8px;border-bottom:1px solid #eee;text-align:right">${money(it.line_total)}</td></tr>`).join('');
const a = d.address || {};
const ship = d.shipping || {};
const eta = (ship.min_days != null && ship.max_days != null) ? `${ship.min_days}–${ship.max_days} ${L.days}` : '';

const html = `<div style="font-family:Arial,Helvetica,sans-serif;max-width:600px;margin:auto;color:#222">
<h2 style="color:#111">${L.subject}</h2>
<p>${L.hi}</p>
<p>${L.intro}</p>
<table style="width:100%;border-collapse:collapse;margin:12px 0"><thead><tr><th style="text-align:left;padding:6px 8px">${L.items}</th><th style="padding:6px 8px">Qty</th><th style="text-align:right;padding:6px 8px">${L.total}</th></tr></thead><tbody>${rows}</tbody></table>
<table style="width:100%;margin:8px 0">
<tr><td>${L.subtotal}</td><td style="text-align:right">${money(d.items_subtotal)}</td></tr>
<tr><td>${L.shipping}</td><td style="text-align:right">${money(d.shipping_cost)}</td></tr>
<tr><td>${L.tax}</td><td style="text-align:right">${money(d.tax)}</td></tr>
<tr><td><strong>${L.total}</strong></td><td style="text-align:right"><strong>${money(d.order_total)}</strong></td></tr>
</table>
<p><strong>${L.ship_to}:</strong><br>${[a.line1, a.line2, [a.postal_code, a.city].filter(Boolean).join(' '), a.state, a.country].filter(Boolean).join('<br>')}</p>
${eta ? `<p><strong>${L.eta}:</strong> ${eta}</p>` : ''}
<p style="margin-top:20px;color:#666">${L.thanks}</p>
</div>`;

return [{ json: { to: p.recipient, subject: L.subject, html } }];
